# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
F=[['拉丁复合词中的 -fendere','击打、推撞；通常不独立使用']]
D=F+[['拉丁 de-“离开” + -fendere → defendere','把攻击挡开 → 保护、防卫']]
O=F+[['拉丁 ob-“对着” + -fendere → offendere','撞上、冲撞 → 伤害、触犯；ob- 在 f 前同化成 of-']]
DS=D+[['拉丁 defens- 词干及防护名词 → 古法语 defens／defense','防护、防御'],['中古英语 defens／defense → defense／defence','防御；后来也指辩护、辩护方']]
OS=O+[['拉丁 offensa → 古法语 offense → 英语 offense／offence','冲撞、伤害 → 冒犯、违法行为；也发展出进攻义']]
WA=[
E('offend','/əˈfend/','冒犯；使不快；违法或触犯','话或行为撞到了别人的感受，也可能越过规则的边界。','历史上是拉丁 ob-“对着” + -fendere“击打”，组合成 offendere；不是现代英语 off + end。',O+[['古法语 ofendre／offendre → 英语 offend','使不快、伤害；违反规范']],'offend someone 常指让对方感到被侮辱或不受尊重。法律语境里的 offend 也可以指违法，并不一定有一个当场生气的人。抓住“冲撞到别人或规则”这个画面，就能把两种用法连起来。','offend someone；offend against a rule；I didn’t mean to offend you.','upset 更宽泛，可能是担忧或悲伤；offend 常带受到侮辱、尊严受损或规范被触犯的感觉。',('I’m sorry; I didn’t mean to offend you.','对不起，我不是有意冒犯你。'),('The report examines why some people offend again after leaving prison.','报告探讨了为什么有些人出狱后再次违法。'),sources=['https://www.etymonline.com/word/offend','https://en.wiktionary.org/wiki/offend']),
E('offense','/əˈfens/；美式体育“进攻方”常读 /ˈɔːfens/ 或 /ˈɑːfens/','冒犯；违法行为；进攻或进攻方〔美式拼写〕','既可以是一次越界，也可以是在比赛中主动向前打的一方。','拉丁 offensa 接 offendere“冲撞”的分词词干，经法语进入英语；与 offence 是拼写差别。',OS,'an offense 可以是一项违法行为；take offense 是因言行而觉得受冒犯。体育里的 offense 则指进攻打法或进攻方，沿着“主动攻击”这条意义发展。常用的 no offense 想表达“无意冒犯”，但不能保证后面的话就不会伤人。','a criminal offense；take offense at something；on offense；no offense intended。','美式多写 offense，英式多写 offence。offensive 在两种拼写体系里一般都用 s。',('She took offense at his dismissive tone.','她觉得他那种不屑的语气很冒犯人。'),('The team needs to improve its offense.','球队需要改善进攻。'),('The report treats the incident as a minor offense.','报告把这起事件视为一次轻微违法行为。'),sources=['https://www.etymonline.com/word/offense','https://en.wiktionary.org/wiki/offense']),
E('offender','英 /əˈfendə/；美 /əˈfendər/','违法者；违规者；造成问题的人或事物','做出了那次越界行为的人；口语也能借来点名主要的问题来源。','offend + -er 可以帮助理解；中古英语已有 offendour／offender 等形式。',O+[['英语 offend → offender','触犯、冒犯 → 实施这种行为的人']],'offender 在法律报道里常说违法者。a repeat offender 是屡次违法或违规的人；日常说 the worst offender，也可能在比较最吵的机器、最费电的设备等，并不真的在指控它犯罪。','a young offender；a repeat offender；the worst offender。','offender 强调触犯法律或规则；suspect 只是受到怀疑的人，语义上不能直接当成已经违法者。',('The program helps young offenders return to school.','这个项目帮助年轻违法者重返学校。'),('Among the noisy machines, the old printer was the worst offender.','在那些吵闹的机器中，老打印机是最烦人的一个。'),sources=['https://en.wiktionary.org/wiki/offender','https://www.etymonline.com/word/offender']),
E('fend','/fend/','抵挡；设法照顾自己','一边把麻烦挡开，一边靠自己撑住生活。','由 defend 缩短而来；不是 defend 历史上在现成英语 fend 前加 de-。',D+[['古法语 defendre → 中古英语 defenden','防护、抵挡'],['英语缩短为 fend','抵挡；后来发展出照顾、供养自己']],'最实用的两组搭配是 fend off 和 fend for oneself。前者像把扑过来的东西推远，可以是攻击、批评或问题；后者指靠自己应付生活、照顾自己。词义从保护自己，走到了为自己的生活负责。','fend off criticism；fend off an attack；fend for oneself。','fend off 强调挡开；fend for oneself 强调自理。不要把 for 和 off 当成可以随意替换的小词。',('She fended off questions about her private life.','她避开了关于私生活的追问。'),('The children are old enough to fend for themselves for an afternoon.','孩子们已经大到可以自己照顾自己一个下午了。'),sources=['https://www.etymonline.com/word/fend','https://en.wiktionary.org/wiki/fend']),
E('defense','/dɪˈfens/；美式体育语境也常读 /ˈdiːfens/','防御；辩护；辩方〔美式拼写〕','把攻击挡在外面；攻击换成指责，就用理由挡回去。','defens- 是拉丁 defendere 的词干变化；英语名词经法语借入，不是英语 defend 临时换一个结尾。',DS,'defense 可以是防守行动、保护措施，也可以是回应指控的辩护。法庭里的 the defense 指辩方；论文答辩也用 defense，因为作者要解释自己的论证如何站得住。它既能指一道实际防线，也能是一组理由。','in defense of someone；a strong defense；the defense team；a thesis defense。','defense 是名词，defend 是动词。英式常写 defence，美式常写 defense。',('She spoke in defense of her colleague.','她为同事说话，替他辩护。'),('The team’s defense improved in the second half.','球队下半场的防守有所改善。'),('He prepared carefully for his thesis defense.','他认真准备了论文答辩。'),sources=['https://www.etymonline.com/word/defense','https://en.wiktionary.org/wiki/defense']),
E('defence','/dɪˈfens/','防御；辩护；辩方〔英式拼写〕','同一套防护或辩护意思，在英式拼写里以 -ce 收尾。','与 defense 同出中古英语 defens／defense；后来的拼写习惯形成英美差别。',DS+[['英式常用拼写 defence','防御、辩护；与美式 defense 对应']],'读到 defence 就直接按 defense 理解，不必寻找另一种词义。英国文本里常见 defence policy、the defence 等搭配。它的形容词仍通常写 defensive，不是把所有同族单词的 s 都改成 c。','a line of defence；in defence of；the defence argued that…','defence 与 defense 的主要差别在拼写习惯，不能用来区分军事防守与法律辩护。',('The wall formed the town’s last line of defence.','这道城墙是镇上的最后一道防线。'),('She wrote an article in defence of public libraries.','她写了一篇维护公共图书馆的文章。'),sources=['https://www.etymonline.com/word/defense','https://en.wiktionary.org/wiki/defence']),
E('defensive','/dɪˈfensɪv/','防御的；戒备的；急于自我辩护的','对方才提一个问题，你已经像举起盾牌一样准备反击。','defens- + -ive 可帮助识别；历史上经法语 defensif 与中世纪拉丁 defensivus 等形式进入英语。',D+[['拉丁 defens- → 中世纪拉丁 defensivus；法语 defensif','用于防御的'],['英语 defensive','防守的；也形容对批评高度戒备的态度']],'a defensive strategy 是守住阵地的策略。说一个人 gets defensive，通常是他把意见听成攻击，马上解释、否认或反驳。这个心理用法不是简单地说他真的遭受了不公平攻击，而是在描述他的应对姿态。','a defensive position；defensive driving；get defensive；be on the defensive。','defensible 是“有理由可以辩护”；defensive 是“正在采取防卫姿态”。一个很 defensive 的回应也可能并不 defensible。',('He became defensive when I asked about the delay.','我问到延误时，他马上摆出了自我辩护的姿态。'),('The team adopted a defensive strategy.','球队采取了防守策略。'),sources=['https://www.etymonline.com/word/defensive','https://en.wiktionary.org/wiki/defensive']),
E('defensively','/dɪˈfensɪvli/','防守地；带着戒备或辩解地','同样一句回答，姿态可能像在交流，也可能像在挡住攻击。','defensive + -ly，把“防御的”变成动作的方式。',D+[['英语 defensive → defensively','防御的 → 以防御方式；带戒备地']],'play defensively 说打法偏防守；reply defensively 说回答时急于维护自己。它不只描述话里有解释，还能描述语气和态度，例如立刻否认责任、把普通提问听成质问。','play defensively；respond defensively；drive defensively。','defensively 描述方式；in defense of someone 说明是在维护谁。一个人可以平静地辩护，并不表现得 defensively。',('She answered defensively and avoided the main question.','她带着辩解的口气回答，避开了主要问题。'),('The team played defensively after taking the lead.','球队取得领先后改打防守。'),sources=['https://en.wiktionary.org/wiki/defensively','https://www.etymonline.com/word/defensive']),
E('defenseless','/dɪˈfensləs/','没有防御能力的；无力自卫的〔美式常用〕','攻击来了，却没有足够的力量、手段或保护来挡住它。','defense + -less“没有”，去掉末尾不发音的 e。',DS+[['英语 defense + -less → defenseless','缺少防护 → 无力抵御的']],'defenseless 可以形容儿童、动物、城镇，也能比喻一个人在某种压力下毫无抵抗办法。重点是处境中缺乏防护，不是在评价对方性格软弱。','a defenseless child；leave someone defenseless；defenseless against something。','helpless 更宽泛，表示没有办法；defenseless 特别突出面对攻击或威胁时没有防护。',('The small animal was defenseless against the larger predator.','这只小动物无力抵御更大的捕食者。'),('The failure left the network defenseless against further attacks.','这次故障使网络失去了抵御进一步攻击的能力。'),sources=['https://en.wiktionary.org/wiki/defenseless','https://www.merriam-webster.com/dictionary/defenseless']),
]
